function hIndex(citations: number[]): number {
  const n = citations.length;

  // h не может быть больше n, поэтому все значения > n считаем как n.
  // buckets[c] — сколько статей имеют c цитирований (c от 0 до n)
  const buckets = new Array<number>(n + 1).fill(0);
  for (const c of citations) {
    buckets[Math.min(c, n)]++;
  }

  // Идём от больших h к меньшим и считаем статьи с >= h цитированиями
  let papers = 0;
  for (let h = n; h >= 0; h--) {
    papers += buckets[h];
    // Нашлось хотя бы h статей с >= h цитированиями — это максимальный h
    if (papers >= h) return h;
  }

  return 0;
}

// Время: O(n) — подсчёт без сортировки
// Память: O(n) — массив корзин
